async def main():
 async with async_playwright()as pw:
  for engine,widths in [('chromium',[320,390,1440]),('webkit',[390])]:
   b=await getattr(pw,engine).launch(args=['--disable-http2']if engine=='chromium'and os.environ.get('J180_HTTP1')else [])
   for w in widths:await check(b,engine,w)
   await edges(b,engine);await b.close()
 (H/os.environ.get('J180_CHECKS','checks.json')).write_text(json.dumps(RESULTS,ensure_ascii=False,indent=2),encoding='utf-8')
